select

from staff_personnel_info
where 1 = 1

    and user_tel = #{userTel,jdbcType=VARCHAR}


    and job_no = #{jobNo,jdbcType=VARCHAR}


    and id_card = #{idCard,jdbcType=VARCHAR}

limit 1;

select count(1)
from staff_personnel_info
where delete_flag =0 and staff_state != 6
and organ_id in (
    select id from staff_organ where 1=1

        and organ_manager_staff_id = #{organManagerStaffId,jdbcType=BIGINT}


        and superior_manager_staff_id = #{superiorManagerStaffId,jdbcType=BIGINT}

)

mapper.update:
UPDATE staff_personnel_info
SET performance = #{performance}
WHERE organ_id = #{id}
